export const MAP_W=52,MAP_H=40;
const inside=(a,x,y)=>x>=a.x&&y>=a.y&&x<a.x+a.w&&y<a.y+a.h;
export function createMuseum(projects){
 const rooms=[
 {name:'Digital spaces',zh:'数字空间',color:'#91c4d4',floor:'#aeb8bc',x:2,y:3,w:18,h:16,areas:[{x:2,y:3,w:18,h:9},{x:2,y:12,w:12,h:7}],points:[[6,7],[15,7],[6,15],[11,15]],ids:['p1','p6','p9','p11']},
 {name:'Living systems',zh:'生命与系统',color:'#a0c69c',floor:'#b8c1a1',x:30,y:2,w:18,h:18,areas:[{x:30,y:2,w:18,h:8},{x:34,y:10,w:14,h:10}],points:[[35,6],[44,6],[38,15],[44,17]],ids:['p3','p8','p4','p13']},
 {name:'Imagined futures',zh:'想象未来',color:'#c9acd5',floor:'#b9a8bc',x:2,y:25,w:26,h:12,areas:[{x:2,y:25,w:18,h:12},{x:20,y:29,w:8,h:8}],points:[[6,29],[15,29],[23,33]],ids:['p2','p7','p5']},
 {name:'Memory & culture',zh:'记忆与文化',color:'#d8b681',floor:'#c9b38e',x:29,y:27,w:20,h:10,areas:[{x:33,y:27,w:16,h:10},{x:29,y:31,w:4,h:6}],points:[[37,31],[45,31],[31,34]],ids:['p10','p12','p14']}];
 const corridors=[{x:12,y:15,w:11,h:4},{x:20,y:7,w:13,h:3},{x:21,y:7,w:3,h:10},{x:29,y:14,w:9,h:4},{x:17,y:23,w:7,h:8},{x:26,y:31,w:10,h:4},{x:29,y:23,w:7,h:9}],garden={x:20,y:12,w:12,h:14},pond={x:24,y:17,w:5,h:5},used=new Set(),exhibits=[];
 for(const [i,room] of rooms.entries())for(const [j,id] of room.ids.entries()){const p=projects.find(p=>p.id===id);if(!p)continue;used.add(id);exhibits.push({id,title:p.title,x:room.points[j][0],y:room.points[j][1],room:i,color:room.color,collider:{left:-1.5,right:1.5,top:-1.5,bottom:.5},trigger:{left:-3.3,right:3.3,top:-2,bottom:3.4}})}
 for(const p of projects.filter(p=>!used.has(p.id))){const i=exhibits.length,point=rooms[Math.floor(i/4)%4].points[i%4]||rooms[3].points[2];exhibits.push({id:p.id,title:p.title,x:point[0],y:point[1],room:Math.floor(i/4)%4,color:rooms[0].color,collider:{left:-1.5,right:1.5,top:-1.5,bottom:.5},trigger:{left:-3.3,right:3.3,top:-2,bottom:3.4}})}
 return {rooms,corridors,garden,pond,exhibits,player:{x:22,y:21},path:[],visited:new Set(),distance:0,facing:1};
}
export function terrain(g,x,y){x=Math.round(x);y=Math.round(y);if(x<1||y<1||x>=MAP_W-1||y>=MAP_H-1)return null;if(inside(g.pond,x,y))return y===19?'bridge':'water';const room=g.rooms.find(r=>r.areas.some(a=>inside(a,x,y)));if(room)return room;return inside(g.garden,x,y)?'garden':g.corridors.some(a=>inside(a,x,y))?'path':null}
export function walkable(g,x,y){const ground=terrain(g,x,y);if(!ground||ground==='water')return false;return !g.exhibits.some(e=>x>e.x+e.collider.left&&x<e.x+e.collider.right&&y>e.y+e.collider.top&&y<e.y+e.collider.bottom)}
export function route(g,from,to){const start={x:Math.round(from.x),y:Math.round(from.y)},target={x:Math.round(to.x),y:Math.round(to.y)};if(!walkable(g,target.x,target.y))return [];const key=p=>p.y*MAP_W+p.x,queue=[start],parents=new Map([[key(start),null]]);for(let i=0;i<queue.length;i++){const p=queue[i];if(p.x===target.x&&p.y===target.y){const path=[];let node=p;while(node){path.unshift(node);node=parents.get(key(node))}return path.slice(1)}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const n={x:p.x+dx,y:p.y+dy},k=key(n);if(!parents.has(k)&&walkable(g,n.x,n.y)){parents.set(k,p);queue.push(n)}}}return []}
export function nearbyExhibit(g,previousId){let best=null,distance=Infinity;for(const e of g.exhibits){const a=e.trigger,dx=g.player.x-e.x,dy=g.player.y-e.y;if(dx<a.left||dx>a.right||dy<a.top||dy>a.bottom)continue;const d=Math.hypot(dx,dy-1);if(d<distance){best=e;distance=d}}const previous=g.exhibits.find(e=>e.id===previousId);if(previous&&best&&best.id!==previous.id){const d=Math.hypot(g.player.x-previous.x,g.player.y-previous.y-1);if(d<distance+.45&&Math.abs(g.player.x-previous.x)<3.5&&g.player.y>previous.y-2&&g.player.y<previous.y+3.6)return previous}return best}
export function stepMuseum(g,input,delta){let dx=input.x,dy=input.y,dt=Math.min(.033,Math.max(0,delta));if(dx||dy)g.path=[];else if(g.path.length){const target=g.path[0],x=target.x-g.player.x,y=target.y-g.player.y,d=Math.hypot(x,y);if(d<.13){g.player={...target};g.path.shift();return true}dx=x/d;dy=y/d}const length=Math.hypot(dx,dy);if(!length)return false;dx/=length;dy/=length;const speed=5.7*dt,old={...g.player},safe=(x,y)=>[-.2,.2].every(ox=>[-.2,.2].every(oy=>walkable(g,x+ox,y+oy)));if(safe(g.player.x+dx*speed,g.player.y))g.player.x+=dx*speed;if(safe(g.player.x,g.player.y+dy*speed))g.player.y+=dy*speed;if(dx)g.facing=dx>0?1:-1;const moved=Math.hypot(g.player.x-old.x,g.player.y-old.y);g.distance+=moved;if(!moved&&g.path.length)g.path=[];return moved>0}
